import{temperatureFigure,hormoneFigure,glucoseFigure,feedbackFigure}from './endo-figures.js?v=20261023-physicscomplete01';
export const endoFilms={
 'endo-temperature':{title:'Temperature detection and response',steps:['Temperature receptors detect a rise; the brain centre coordinates a response.','Too hot: skin vessels dilate and sweat is produced.','A separate cold-condition example: temperature receptors signal the change.','Too cold: vessels constrict, sweating stops and skeletal muscles shiver.'],duration:14,note:'Both-tier response-recognition example. Skin vessels change diameter in place. Two different starting conditions are replayed; real body temperature need not alternate. Displayed droplets, flow, scale and timing are symbolic. Detailed energy-transfer explanations are in Higher-only teaching and tasks.',render:p=>temperatureFigure({state:p<.5?'hot':'cold',progress:(p*2)%1})},
 'endo-hormone':{title:'Gland → blood → target',steps:['An endocrine gland secretes a chemical hormone into blood.','Blood transports the hormone around the body.','A suitable target responds to the hormone signal.','Some pituitary hormones stimulate other endocrine glands to secrete hormones.'],duration:12,note:'A generic chemical-signal pathway with a slowed diamond tracer, not a literal blood-flow or molecular-speed model. Not every organ responds to every hormone. The final stage illustrates the principle of pituitary coordination; this loop does not mean a hormone always returns to its original gland.',render:p=>hormoneFigure({progress:p,state:p>=.75?'pituitary':''})},
 'endo-insulin':{title:'Insulin: signal, uptake, storage',steps:['The pancreas detects high blood glucose concentration.','The pancreas secretes insulin: the hormone is a signal.','Glucose moves from blood into cells; excess glucose can form glycogen in liver and muscle.','Uptake and storage lower blood glucose towards a suitable level.'],duration:14,note:'Glucose units are circles; the separate diamond is an insulin signal. Linked units represent glycogen. Symbolic units are conserved between blood, transfer and store, but are not mmol/L or real molecule counts. This is a worked example, not an insulin-dose or patient simulation. Reset replays the example.',render:p=>glucoseFigure({kind:'insulin',signal:p>=.25,progress:p<.25?0:(p-.25)/.75})},
 'endo-glucagon':{title:'Glucagon: reverse the fall',steps:['The pancreas detects low blood glucose.','Glucagon signals the liver to convert stored glycogen into glucose.','Glucose is released into the blood, raising its concentration.','As suitable levels return, the corrective glucagon drive decreases.'],duration:14,note:'Higher-only worked low-glucose correction. Glucagon is a signal, not a sugar converted into glucose. Liver glycogen supplies the glucose. Counts and rates are symbolic; real regulation uses a suitable range, not a fixed movie schedule. The final step shows reduced corrective drive; reset repeats one example.',render:p=>p<.78?glucoseFigure({kind:'glucagon',signal:p>=.25,progress:p<.25?0:(p-.25)/.53}):feedbackFigure({state:'restored',progress:(p-.78)/.22})}
};
